const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });

  // 1. Geometry & Time Definitions
  const parisPoint = ee.Geometry.Point(2.3522, 48.8566); // Center of Paris
  const targetDate = '2024-08-06';
  const targetTime = '13:40'; // 1:40 PM local time

  // Define a small buffer around the point for a more robust sample
  const studyArea = parisPoint.buffer(1000); // 1 km buffer

  // MODIS MYD11A1 (Aqua) has overpass times in the afternoon, often closer to 1:30 PM local time.
  // MOD11A1 (Terra) is morning. So, MYD11A1 is a better choice for '1:40 pm'.
  // LST is in Kelvin * 0.02. To get Celsius, convert K to C: C = (K * 0.02) - 273.15
  const LST_THRESHOLD_CELSIUS = 32;
  const LST_THRESHOLD_KELVIN_FACTOR = (LST_THRESHOLD_CELSIUS + 273.15) / 0.02;

  console.log(`Checking LST in Paris on ${targetDate} around ${targetTime} local time.`);

  try {
    // 2. Data Acquisition & Check
    // The date "August 6, 2024" is in the future relative to the current data availability timeline
    // for satellite imagery like MODIS. Data typically has a processing lag of a few days to weeks.
    // Therefore, it's highly improbable that data for this specific future date is available yet.

    // To demonstrate the check for future data:
    const collection = ee.ImageCollection('MODIS/061/MYD11A1')
      .filterBounds(studyArea)
      .filterDate(targetDate, ee.Date(targetDate).advance(1, 'day'));

    const imageCount = await collection.size().getInfo();
    console.log(`Images found for ${targetDate}: ${imageCount}`);

    if (imageCount === 0) {
      console.log("No images found for the specified date (August 6, 2024).");
      console.log("This is expected as data for future dates is not yet available in the archive.");
      return console.log("C1");
    }

    // If, hypothetically, data *were* available (e.g., if the question was for a past date):
    const lstImage = collection.select('LST_Day').first();

    if (!lstImage) {
      console.log("No specific LST image found after initial filter.");
      return console.log("C1");
    }

    // 3. Processing (Cloud Masking for MODIS is often handled internally for LST, but a basic check is good)
    // MODIS LST QA band bits can indicate quality, but for simplicity here we assume primary LST is usable.
    // The 'LST_Day' band itself usually has fill values for clouds.

    const scale = 1000; // MODIS LST resolution is 1km

    // Reduce region to get mean LST
    const meanLSTKelvinFactor = await lstImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: studyArea,
      scale: scale,
      maxPixels: 1e9
    }).get('LST_Day').getInfo();

    if (meanLSTKelvinFactor === null || meanLSTKelvinFactor === undefined) {
      console.log("Mean LST calculation returned null/undefined, possibly due to no valid pixels.");
      return console.log("C3");
    }

    // Convert from Kelvin * 0.02 to Celsius
    const meanLSTCelsius = (meanLSTKelvinFactor * 0.02) - 273.15;

    // Validate if the result is a sensible number
    if (isNaN(meanLSTCelsius) || meanLSTCelsius < -50 || meanLSTCelsius > 70) {
        console.log(`Calculated LST (${meanLSTCelsius.toFixed(2)} C) is out of expected range.`);
        return console.log("C3");
    }

    console.log(`Mean LST in Paris on ${targetDate} was: ${meanLSTCelsius.toFixed(2)} C`);

    // 5. Validation & Final Answer
    if (meanLSTCelsius > LST_THRESHOLD_CELSIUS) {
      console.log("A");
    } else {
      console.log("B");
    }

  } catch (error) {
    console.error("An error occurred during analysis:", error);
    if (error.message.includes("does not exist") || error.message.includes("Incorrect band name")) {
      return console.log("D");
    }
    return console.log("C3"); // Generic failure
  }
}

runAnalysis();
